use std::io::{self, Read};
use std::fs;
use std::time::Instant;
// These constants represent the RISC-V ELF and the image ID generated by risc0-build.
// The ELF is used for proving and the ID is used for verification.
use clap::{Parser, Subcommand};
use hex;
use methods::{GUEST_CODE_FOR_ZK_PROOF_ELF, GUEST_CODE_FOR_ZK_PROOF_ID};
use risc0_zkvm::{default_prover, ExecutorEnv, InnerReceipt, ProverOpts, Receipt};
use k256::PublicKey;
use serde::{Deserialize, Serialize};
use std::str::FromStr;
use musig2::secp::Scalar;

/// Journal output from the guest program
/// All data is wrapped in this single structure for atomic commitment
#[derive(Debug, Clone, Serialize, Deserialize)]
struct JournalOutput {
    /// The public key (hex string)
    pubkey: String,
    /// The public nonce (hex string)
    pubnonce: String,
    /// Challenge parity bit
    challenge_parity: u8,
    /// Nonce parity bit
    nonce_parity: u8,
    /// The b value (hex string)
    b: String,
    /// The e value (hex string)
    e: String,
}

#[derive(Debug, Parser)]
#[command(name = "zk-musig")]
#[command(about = "Zero-knowledge proof generation and verification for MuSig2")]
#[command(long_about = "Zero-knowledge proof generation and verification for MuSig2\n\n\
    This tool provides a CLI for generating and verifying zero-knowledge proofs\n\
    for MuSig2 multi-signature operations with blinding factors.\n\n\
    Output format: All commands output JSON to stdout, progress to stderr")]
#[command(version)]
struct Args {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Debug, Subcommand)]
enum Commands {
    /// Generate a zero-knowledge proof for MuSig2 signature
    ///
    /// EXAMPLES:
    ///     # Generate proof from config file
    ///     zk-musig prove --config config.json --output proof.json
    ///
    ///     # Use fast proof type
    ///     zk-musig prove --config config.json --proof-type fast
    ///
    ///     # Read config from stdin, output to stdout
    ///     cat config.json | zk-musig prove --config -
    #[command(verbatim_doc_comment)]
    Prove {
        /// Path to configuration JSON file (use '-' for stdin)
        ///
        /// Config format:
        ///   {
        ///     "coeff_salt": "hex_string_32_bytes",
        ///     "blinding_factors": [["alpha", "beta", "gamma"], ...],
        ///     "pubkeys": ["hex_pubkey1", "hex_pubkey2", ...],
        ///     "pubnonces": ["hex_nonce1", "hex_nonce2", ...],
        ///     "message": "message_to_sign",
        ///     "signer_index": 0
        ///   }
        #[arg(short, long, value_name = "FILE")]
        config: String,

        /// Proof type to generate
        ///
        /// Types: default, fast, succinct, groth16, composite
        /// Fast proofs are quicker to generate but larger
        #[arg(short = 't', long, value_name = "TYPE")]
        #[arg(value_parser = ["default", "fast", "succinct", "groth16", "composite"])]
        proof_type: Option<String>,

        /// Output file for the proof (stdout if not specified)
        #[arg(short, long, value_name = "FILE")]
        output: Option<String>,
    },
    /// Verify a zero-knowledge proof
    ///
    /// EXAMPLES:
    ///     # Verify proof from file
    ///     zk-musig verify --input proof.json
    ///
    ///     # Verify from stdin
    ///     cat proof.json | zk-musig verify
    ///
    ///     # Verify and capture output
    ///     zk-musig verify --input proof.json > result.json
    #[command(verbatim_doc_comment)]
    Verify {
        /// Path to proof file to verify (use '-' for stdin, default is stdin)
        ///
        /// Expects JSON format with "proof" field containing hex-encoded proof
        #[arg(short, long, value_name = "FILE")]
        input: Option<String>,
    },
}

/// Configuration for proof generation
///
/// All cryptographic values should be provided as lowercase hex strings.
#[derive(Deserialize, Serialize, Debug, Clone)]
struct Config {
    /// Coefficient salt for key aggregation (hex-encoded, 32 bytes)
    pub coeff_salt: String,

    /// Blinding factors as tuples of (alpha, beta, gamma) for each signer (hex-encoded scalars)
    /// Each scalar should be a 32-byte value encoded as a 64-character hex string
    pub blinding_factors: Vec<(String, String, String)>,

    /// Public keys for all signers (hex-encoded, 33 bytes compressed format)
    pub pubkeys: Vec<String>,

    /// Public nonces for all signers (hex-encoded, 66 bytes)
    pub pubnonces: Vec<String>,

    /// Message to sign (hex-encoded bytes)
    /// This is typically the sighash of a transaction
    pub message: String,

    /// Index of the signer this proof is for (0-based)
    pub signer_index: u32,
}

/// Output from proof generation or verification
///
/// Contains the proof and extracted journal data with cryptographic commitments.
#[derive(Serialize, Debug)]
struct ProofOutput {
    /// Whether the operation succeeded
    pub success: bool,

    /// Whether the proof was verified successfully
    pub verified: bool,

    /// The proof itself (hex-encoded binary data)
    pub proof: String,

    /// Extracted journal data from the proof
    pub journal: JournalData,

    /// Type of proof generated (composite, succinct, groth16, etc.)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub proof_type: Option<String>,
}

/// Journal data committed to in the zero-knowledge proof
///
/// All cryptographic values are hex-encoded strings.
#[derive(Serialize, Debug)]
struct JournalData {
    /// Public key of the signer (hex-encoded, 33 bytes compressed format)
    pub pubkey: String,

    /// Public nonce used by the signer (hex-encoded, 66 bytes)
    pub pubnonce: String,

    /// Parity bit for the challenge (0 or 1)
    pub challenge_parity: u8,

    /// Parity bit for the signing nonce (0 or 1)
    pub nonce_parity: u8,

    /// Blinded nonce coefficient b' = b + gamma (hex-encoded scalar, 32 bytes)
    pub b: String,

    /// Blinded challenge e' (hex-encoded scalar, 32 bytes)
    pub e: String,
}

/// Input for proof verification
#[derive(Deserialize, Debug)]
struct ProofInput {
    /// The proof to verify (hex-encoded binary data)
    pub proof: String,
}

fn main() {
    // Initialize tracing. In order to view logs, run `RUST_LOG=info cargo run`
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::filter::EnvFilter::from_default_env())
        .init();

    let args = Args::parse();

    match args.command {
        Commands::Verify { input } => {
            verify_proof(input);
        }
        Commands::Prove { config, proof_type, output } => {
            generate_proof(config, proof_type, output);
        }
    }
}

fn read_input(input_file: Option<String>) -> String {
    match input_file.as_deref() {
        None | Some("-") => {
            // Read from stdin
            let mut buffer = String::new();
            io::stdin().read_to_string(&mut buffer).unwrap();
            buffer
        }
        Some(path) => {
            // Read from file
            fs::read_to_string(path).unwrap()
        }
    }
}

fn write_output(output_file: Option<String>, content: String) {
    match output_file {
        None => {
            // Write to stdout
            println!("{}", content);
        }
        Some(path) => {
            // Write to file
            fs::write(path, content).unwrap();
        }
    }
}

fn verify_proof(input_file: Option<String>) {
    eprintln!("Reading proof...");
    let content = read_input(input_file);

    // Parse JSON input
    let input: ProofInput = serde_json::from_str(&content).unwrap();
    let hex_string = input.proof;

    let bin = hex::decode(hex_string.trim()).unwrap();
    let receipt: Receipt = bincode::deserialize(&bin).unwrap();

    eprintln!("Verifying proof...");
    let start = Instant::now();
    let verified = receipt.verify(GUEST_CODE_FOR_ZK_PROOF_ID).is_ok();
    let duration = start.elapsed();

    if verified {
        eprintln!("Proof verified successfully in {}ms", duration.as_millis());
    } else {
        eprintln!("Proof verification failed");
    }

    let output = create_proof_output(&receipt, verified, None);
    let json_output = serde_json::to_string_pretty(&output).unwrap();
    write_output(None, json_output);
}

fn create_proof_output(receipt: &Receipt, verified: bool, proof_type: Option<String>) -> ProofOutput {
    // Serialize receipt to hex
    let receipt_bytes = bincode::serialize(&receipt).unwrap();
    let hex_proof = hex::encode(receipt_bytes);

    // Extract proof type from receipt if not provided
    let proof_type = proof_type.or_else(|| {
        Some(match &receipt.inner {
            InnerReceipt::Composite(_) => "composite".to_string(),
            InnerReceipt::Succinct(_) => "succinct".to_string(),
            InnerReceipt::Groth16(_) => "groth16".to_string(),
            InnerReceipt::Fake(_) => "fake".to_string(),
            _ => "unknown".to_string(),
        })
    });

    // Decode the entire journal output structure in one operation
    let journal_output: JournalOutput = receipt.journal.decode().unwrap();

    ProofOutput {
        success: true,
        verified,
        proof: hex_proof,
        journal: JournalData {
            pubkey: journal_output.pubkey,
            pubnonce: journal_output.pubnonce,
            challenge_parity: journal_output.challenge_parity,
            nonce_parity: journal_output.nonce_parity,
            b: journal_output.b,
            e: journal_output.e,
        },
        proof_type,
    }
}

fn validate_config(cfg: &Config) {
    // Validate coeff_salt
    if let Err(e) = hex::decode(&cfg.coeff_salt) {
        eprintln!("Error: Invalid coeff_salt hex: {}", e);
        std::process::exit(2);
    }
    let salt_bytes = hex::decode(&cfg.coeff_salt).unwrap();
    if salt_bytes.len() != 32 {
        eprintln!("Error: coeff_salt must be exactly 32 bytes, got {}", salt_bytes.len());
        std::process::exit(2);
    }

    // Validate arrays have matching lengths
    if cfg.pubkeys.len() != cfg.pubnonces.len() {
        eprintln!("Error: pubkeys count ({}) doesn't match pubnonces count ({})",
            cfg.pubkeys.len(), cfg.pubnonces.len());
        std::process::exit(2);
    }

    if cfg.pubkeys.len() != cfg.blinding_factors.len() {
        eprintln!("Error: pubkeys count ({}) doesn't match blinding_factors count ({})",
            cfg.pubkeys.len(), cfg.blinding_factors.len());
        std::process::exit(2);
    }

    // Validate signer_index is within bounds
    if cfg.signer_index >= cfg.pubkeys.len() as u32 {
        eprintln!("Error: signer_index ({}) is out of bounds (max: {})",
            cfg.signer_index, cfg.pubkeys.len() - 1);
        std::process::exit(2);
    }

    // Validate pubkeys are valid hex
    for (i, pk) in cfg.pubkeys.iter().enumerate() {
        if let Err(e) = hex::decode(pk) {
            eprintln!("Error: Invalid pubkey[{}] hex: {}", i, e);
            std::process::exit(2);
        }
    }

    // Validate blinding factors are valid hex scalars
    for (i, (alpha, beta, gamma)) in cfg.blinding_factors.iter().enumerate() {
        if let Err(e) = Scalar::from_str(alpha) {
            eprintln!("Error: Invalid alpha in blinding_factor[{}]: {}", i, e);
            std::process::exit(2);
        }
        if let Err(e) = Scalar::from_str(beta) {
            eprintln!("Error: Invalid beta in blinding_factor[{}]: {}", i, e);
            std::process::exit(2);
        }
        if let Err(e) = Scalar::from_str(gamma) {
            eprintln!("Error: Invalid gamma in blinding_factor[{}]: {}", i, e);
            std::process::exit(2);
        }
    }

    eprintln!("Configuration validated successfully");
}

fn generate_proof(config_path: String, proof_type: Option<String>, output_file: Option<String>) {
    // Read config from file or stdin
    let config_content = if config_path == "-" {
        read_input(None)
    } else {
        read_input(Some(config_path))
    };

    let cfg: Config = serde_json::from_str(&config_content).unwrap();

    // Validate config before expensive operations
    validate_config(&cfg);

    let coeff_salt: [u8; 32] = hex::decode(cfg.coeff_salt).unwrap().try_into().unwrap();

    let blinding_factors: Vec<([u8;32], [u8;32], [u8;32])> = cfg
        .blinding_factors
        .iter()
        .map(|(alpha, beta, gamma)| {
            (
                Scalar::from_str(alpha).unwrap().into(),
                Scalar::from_str(beta).unwrap().into(),
                Scalar::from_str(gamma).unwrap().into(),
            )
        })
        .collect();

    let pubkeys: Vec<PublicKey> = cfg.pubkeys.iter().map(|pk| parse_pubkey(pk)).collect();

    let env = ExecutorEnv::builder()
        .write(&cfg.signer_index)
        .unwrap()
        .write(&coeff_salt)
        .unwrap()
        .write(&pubkeys)
        .unwrap()
        .write(&blinding_factors)
        .unwrap()
        .write(&cfg.pubnonces)
        .unwrap()
        .write(&cfg.message)
        .unwrap()
        .build()
        .unwrap();

    let prover_opts: ProverOpts = match proof_type.as_deref() {
        None | Some("default") => {
            eprintln!("Using default proof type");
            ProverOpts::default()
        }
        Some("fast") => {
            eprintln!("Using fast proof type");
            ProverOpts::fast()
        }
        Some("succinct") => {
            eprintln!("Using succinct proof type");
            ProverOpts::succinct()
        }
        Some("groth16") => {
            eprintln!("Using groth16 proof type");
            ProverOpts::groth16()
        }
        Some("composite") => {
            eprintln!("Using composite proof type");
            ProverOpts::composite()
        }
        _ => {
            eprintln!("Error: Invalid proof type");
            return;
        }
    };

    // Obtain the default prover.
    let prover = default_prover();

    eprintln!("Generating proof...");
    let start = Instant::now();

    // Proof information by proving the specified ELF binary.
    // This struct contains the receipt along with statistics about execution of the guest
    let prove_info = prover
        .prove_with_opts(env, GUEST_CODE_FOR_ZK_PROOF_ELF, &prover_opts)
        .unwrap();

    let duration = start.elapsed();
    eprintln!("Proof generated successfully in {:.2}s", duration.as_secs_f64());

    // extract the receipt.
    let receipt = prove_info.receipt;

    // The receipt was verified at the end of proving, but the below code is an
    // example of how someone else could verify this receipt.
    let verified = receipt.verify(GUEST_CODE_FOR_ZK_PROOF_ID).is_ok();

    // Create JSON output using shared helper
    let output = create_proof_output(&receipt, verified, proof_type);
    let json_output = serde_json::to_string_pretty(&output).unwrap();

    // Write output to file or stdout
    write_output(output_file, json_output);
}

fn parse_pubkey(pub_str: &str) -> PublicKey {
    let pk_bytes = hex::decode(pub_str).unwrap();
    let pk = PublicKey::from_sec1_bytes(&pk_bytes).unwrap();
    pk
}
